import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"豫","description":"焦氏易林注 - 豫","frontmatter":{"title":"豫","description":"焦氏易林注 - 豫"},"headers":[],"relativePath":"zh/classics/jiaoyilin/016.md","filePath":"zh/classics/jiaoyilin/016.md"}'),l={name:"zh/classics/jiaoyilin/016.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="豫" tabindex="-1">豫 <a class="header-anchor" href="#豫" aria-label="Permalink to “豫”">​</a></h1><h3 id="豫-1" tabindex="-1">豫 <a class="header-anchor" href="#豫-1" aria-label="Permalink to “豫”">​</a></h3><h3 id="豫之乾" tabindex="-1">豫之乾 <a class="header-anchor" href="#豫之乾" aria-label="Permalink to “豫之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>龍馬上山，絕無水泉。喉焦唇乾，口不能言。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《訟》，此用《豫》象。</p><h3 id="豫之坤" tabindex="-1">豫之坤 <a class="header-anchor" href="#豫之坤" aria-label="Permalink to “豫之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>蔡侯朝楚，留連江濱。逾時厯月，思其後君。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>左氏定五年：蔡侯朝，楚子常求其裘，弗與，乃留蔡侯弗使歸。豫震為草莽、為蔡、為楚、為諸侯，坎陷，故流連，坎水故曰江濱。艮為時，坎為月、為思，震為君。全用《豫》象。</p><h3 id="豫之屯" tabindex="-1">豫之屯 <a class="header-anchor" href="#豫之屯" aria-label="Permalink to “豫之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>文厄羑里，湯困夏台。仁聖不害，數困何憂。免於縲紲，為世雄侯。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>中爻坤為文、為里，坤閉故厄。坎為水，艮火，故曰湯、曰夏。艮為台，震為仁，坎為聖，坤為害。坎為困、為憂，巽為縲紲，巽伏故免。震為雄、為侯。○紲，從汲古，宋元本作索。雄，依宋元本，汲古作明。《史記周本紀》：&quot;紂囚文王於羑里&quot;，《殷本紀》：&quot;夏桀囚湯於夏台&quot;。</p><h3 id="豫之蒙" tabindex="-1">豫之蒙 <a class="header-anchor" href="#豫之蒙" aria-label="Permalink to “豫之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>典冊法書，藏在蘭台。雖遭亂潰，獨不遇災。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。</p><h3 id="豫之需" tabindex="-1">豫之需 <a class="header-anchor" href="#豫之需" aria-label="Permalink to “豫之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>氈裘膻國，文禮不飭。跨馬控弦，伐我都邑。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>伏坤為裘、為文禮、為馬、為我、為都邑，謂匈奴寇邊也。</p><h3 id="豫之訟" tabindex="-1">豫之訟 <a class="header-anchor" href="#豫之訟" aria-label="Permalink to “豫之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>星隕如雨，力弱無輔。強陰制陽，不得安土。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>《左傳莊七年》：&quot;星隕如雨&quot;。離為星，坎為雨，風隕，伏象，明夷，明入地中，故曰陰制陽。坤為土。○第三句宋元本作&quot;強陽制陰&quot;，從汲古。</p><h3 id="豫之師" tabindex="-1">豫之師 <a class="header-anchor" href="#豫之師" aria-label="Permalink to “豫之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>蝗嚼我稻，驅不我去。實穗無有，但見空槁。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《大壯》。</p><h3 id="豫之比" tabindex="-1">豫之比 <a class="header-anchor" href="#豫之比" aria-label="Permalink to “豫之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>虎飢欲食，為蝟所伏。禹導龍門，避咎除患，元醜以安。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，坤虛，故飢。伏兌為食，坎為蝟、為伏，伏乾為王、為龍、為門，故曰禹導龍門。坎為患、為隱伏，故曰避咎除患。坤為醜、為安。○所伏，依汲古，宋元本作而伏，非。《史記龜策傳》：&quot;蝟能伏虎，見鵲而仰。&quot;</p><h3 id="豫之小畜" tabindex="-1">豫之小畜 <a class="header-anchor" href="#豫之小畜" aria-label="Permalink to “豫之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>蝙蝠夜藏，不敢晝行。酒為酸漿，魴臰鮑羹。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為蝙蝠，伏坎為夜、為藏，離為晝，震為行，震伏，故不晝行。坎為酒漿，巽為魚、為臰，故曰魴臰鮑羹。○鮑，元本作飽，非，依宋本、汲古。臰同臭。</p><h3 id="豫之履" tabindex="-1">豫之履 <a class="header-anchor" href="#豫之履" aria-label="Permalink to “豫之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>精華墜落，形體醜惡。齟齬挫頓，枯槁腐蠧。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>兌為華，風隕，故墜落。伏坤為形、為醜惡，兌為口，正反兌相對故齟齬。離為枯槁，巽為腐蠧。○兌為華可釋《大過》。</p><h3 id="豫之泰" tabindex="-1">豫之泰 <a class="header-anchor" href="#豫之泰" aria-label="Permalink to “豫之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>兩足不獲，難以遠行。疾步不能，後旅失時。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>互震為足，兌卦數二，故曰兩足，兌毀故不獲，故不行。震為後、為時，坤喪故失時。</p><h3 id="豫之否" tabindex="-1">豫之否 <a class="header-anchor" href="#豫之否" aria-label="Permalink to “豫之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>令妻壽母，宜家無咎。君子之歡，得以長久。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為妻，乾善故曰令妻。坤為母，艮壽，故曰壽母。艮為家、為君子，伏震為樂，故曰歡。巽為長，艮為久。</p><h3 id="豫之同人" tabindex="-1">豫之同人 <a class="header-anchor" href="#豫之同人" aria-label="Permalink to “豫之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>飢蠶作室，緡多亂纏，端不可得。巽為蟲、為蠶，離虛，故曰飢蠶。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>伏坎為室，巽為緡，離為亂。○飢蠶，宋元本作蠶飢。緡，宋本作昬，元本作緒，均依汲古。端，丁宴依《御覽》校，宋本、汲古皆作緒。</p><h3 id="豫之大有" tabindex="-1">豫之大有 <a class="header-anchor" href="#豫之大有" aria-label="Permalink to “豫之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>子鋤執麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《同人》。○經，宋本作元，元作陰，皆非，依汲古《訟》之《同人》校，汲古只此不訛，餘皆訛作陰，蓋以經字不協而妄改，豈知麟音苓，心音惺，古與經字皆協，而宋元本改為陰聖尤失解。</p><h3 id="豫之謙" tabindex="-1">豫之謙 <a class="header-anchor" href="#豫之謙" aria-label="Permalink to “豫之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>螟蟲為賊，害我稼穡。盡禾殫麥，秋無所得。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《節》。○殫，宋元本皆作單。</p><h3 id="豫之豫" tabindex="-1">豫之豫 <a class="header-anchor" href="#豫之豫" aria-label="Permalink to “豫之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>冰將泮散，鳴雁噰噰。丁男長女，可以會同。生育聖人。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為冰，下臨艮火，故曰泮散。艮為雁，震鳴，故曰噰噰。伏兌納丁，《晉書李密傳》：&quot;零丁孤苦&quot;，丁男，言孤男無配偶也。巽為長女，震為生，坎為聖，言少男長女及冰未泮而婚嫁也。《周禮媒氏》疏引《韓詩傳》：古者霜降逆女，冰泮殺止。按：《詩邶風》：&quot;士如歸妻，迨冰未泮&quot;，據《韓詩》是冰泮後禁嫁也，荀子及家語皆同韓詩說，鄭誤。○聖，從宋元本，汲古作賢。噰噰，從宋元本，汲古作雍雍，與毛詩字異。</p><h3 id="豫之隨" tabindex="-1">豫之隨 <a class="header-anchor" href="#豫之隨" aria-label="Permalink to “豫之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>憂在腹內，山崩為疾。禍起蕭牆，竟制其國。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>互大坎為憂，離為腹，艮為山，震為覆艮，故曰山崩。巽為草莽，艮為牆，故曰蕭牆。艮為國。○以覆艮為山崩可知京謂&quot;崩來無咎&quot;之所本以艮為國，可得《易》各處國邑之象。</p><h3 id="豫之蠱" tabindex="-1">豫之蠱 <a class="header-anchor" href="#豫之蠱" aria-label="Permalink to “豫之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>茹芝餌黃，飲食玉瑛。神與流通，長無憂凶。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為芝、為黃，兌口故曰茹、曰餌、曰飲食。震為玉、為神、為樂，故不憂。此言神仙導引之事。黃，黃精也。</p><h3 id="豫之臨" tabindex="-1">豫之臨 <a class="header-anchor" href="#豫之臨" aria-label="Permalink to “豫之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>一夫兩心，歧刺不深。所為無功，求事不成。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為夫，坤為心，數二，故曰兩心、曰歧。兌毀折故無功，故不成。坤為事。○歧，宋元本作、作拔，皆非，依宋本《噬嗑》之《豐》校。《隴上記》：&quot;狄梁公墓棘直而不歧&quot;，歧，尖也，故曰棘刺。又《後漢張堪傳》：&quot;麥穗兩歧，註：一莖兩穗&quot;。亦一證也。又《易坤靈圖》引亦作拔刺。</p><h3 id="豫之觀" tabindex="-1">豫之觀 <a class="header-anchor" href="#豫之觀" aria-label="Permalink to “豫之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>十里望煙，渙散四分。形容滅亡，終不見君。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為里，數十。艮為望。煙，音因，與氤通。班固典引煙煙熅熅，煙熅，天地氣也，與絪縕同。艮陽在上，坤在下，天地氣接，故曰望煙。巽風為散，數四，故曰四分。坤為形、為死，故滅亡。乾伏故不見君。○四分，依宋元本，汲古作四方，以與亡協，豈知煙音因，作分乃協。</p><h3 id="豫之噬嗑" tabindex="-1">豫之噬嗑 <a class="header-anchor" href="#豫之噬嗑" aria-label="Permalink to “豫之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>張弓控弩，經涉山道。雖有伏虎，誰敢害諸。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>坎為弓、為弩，震為張，艮為山道、為虎，坎伏，故曰伏虎。坎為害。○諸，依宋元本，以與虎韻，汲古作者。</p><h3 id="豫之賁" tabindex="-1">豫之賁 <a class="header-anchor" href="#豫之賁" aria-label="Permalink to “豫之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>泉閉澤竭，主母饑渴。君子困窮，乃徐有說。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為泉，坎伏故閉，下火故竭。震為主，伏巽為母，離虛而燥，故饑渴。艮為君子，坎為困。說脫通，言脫去困窮也。○主母，宋元本作王母，依汲古。</p><h3 id="豫之剝" tabindex="-1">豫之剝 <a class="header-anchor" href="#豫之剝" aria-label="Permalink to “豫之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>野鳶山鵲，弈棋六博。三梟四散，主人勝客。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為鳶、為鵲、為梟、為山，元本註三梟四散，皆古局戲名，按：《戰國楚策》雲：&quot;夫梟棊之所以能為者，以散棊佐之也，夫一梟之不勝，五散亦明矣&quot;，按：黃山谷詩：&quot;安知樗蒲局，臨關敗三梟&quot;，今博戲失傳，故不知其義。○鳶，從宋元本，汲古作猿。</p><h3 id="豫之復" tabindex="-1">豫之復 <a class="header-anchor" href="#豫之復" aria-label="Permalink to “豫之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>羊驚馬走，上下揮擾。鼓音不絕，頃公奔敗。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為驚、為羊、為馬、為走、為鼓、為音，坤為頃，震為公，故曰頃公。震為奔，坤為敗。《左傳成二年》：&quot;晉卻克與齊頃公戰，晉人援桴而鼓之，頃公奔敗&quot;。○頃，汲古訛項，依宋本。</p><h3 id="豫之無妄" tabindex="-1">豫之無妄 <a class="header-anchor" href="#豫之無妄" aria-label="Permalink to “豫之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>黃帝神明，八子聖聰。俱受大福，天下康平。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為黃、為帝、為神，艮為明，數八，震子，故曰八子。乾為聖聰、為大福、為天，震陽在下，故曰天下。《左傳》：&quot;高陽氏有才子八人&quot;，林所本也。○康平，依宋元本，汲古作平康。</p><h3 id="豫之大畜" tabindex="-1">豫之大畜 <a class="header-anchor" href="#豫之大畜" aria-label="Permalink to “豫之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>輕車醊祖，猋風暴起。泛亂祭器，飛揚鼓舞。明神降佑，道無害寇。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為車、為祭祀，故曰醊祖。祖者，將行犯軷之祭，《詩大雅》&quot;仲山甫出祖&quot;是也。伏巽為風，進退，故曰猋風。震為器，兌毀故泛亂。震為飛揚、為鼓舞、為明神、為福佑、為道，坤為害、為殺，坤伏故無。○首句原作&quot;住馬醊酒&quot;，猋作疾，第四句作&quot;飛揚位卓&quot;，卓，宋元本又作草，茲依汲古《坎》之《巽》校，祇泛字依本文。</p><h3 id="豫之頤" tabindex="-1">豫之頤 <a class="header-anchor" href="#豫之頤" aria-label="Permalink to “豫之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>螣蛇乘龍，宋鄭飢凶，民食草蓬。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為龍，坤為蛇，在震上故曰乘龍。《說文》以木架屋為宋，故艮為宋。鄭，《說文》地町町然平也，故坤為鄭、為凶、為民。震為食、為草莽。</p><h3 id="豫之大過" tabindex="-1">豫之大過 <a class="header-anchor" href="#豫之大過" aria-label="Permalink to “豫之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>揚水潛鑿，使石潔白。里素表朱，游戲皋沃。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>得君所欲，心志娛樂。詳《否》之《師》。○按：汲古作&quot;衣素表朱&quot;，宋元本作&quot;里素表朱&quot;，《毛詩》詁襮為領，謂衣素而黼領朱也，與《爾雅》合，後儒據高誘《呂覽》註及班賦詁襮為表以攻毛，豈知素衣朱表語已不合，茲按林詞亦詁襮為表，然曰里素，則讀衣為里也。素里朱襮，義始分明。○沃，汲古作澤，依宋元本。</p><h3 id="豫之坎" tabindex="-1">豫之坎 <a class="header-anchor" href="#豫之坎" aria-label="Permalink to “豫之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>西過虎廬，驚我前驅，雖憂不危。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎位西，中爻艮為虎、為廬，震為驚，坎為憂危。○危，從汲古本，宋元作尤，非。</p><h3 id="豫之離" tabindex="-1">豫之離 <a class="header-anchor" href="#豫之離" aria-label="Permalink to “豫之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>衣成無袖，不知所穿。客指東西，未得便安。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。震為衣，坎為穿，震為袖，中爻正覆震相對，故曰無袖。又中爻亦正覆艮，艮止，故不知所穿。震為客、為東，兌為西。○袖，依宋本，汲古作開。</p><h3 id="豫之咸" tabindex="-1">豫之咸 <a class="header-anchor" href="#豫之咸" aria-label="Permalink to “豫之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>晨風文翰，隨時就溫。雌雄相和，不憂殆危。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>《詩》：&quot;鴥彼晨風&quot;，《傳》鸇也。巽為風，伏震為晨、為翰，坤為文，故曰文翰。文翰，即晨風。詳《大過》之《豫》。艮為時、為火，故曰溫。震雄巽雌，兌口震鳴，故曰和。○殆危，依汲古，宋本作危殆。</p><h3 id="豫之恒" tabindex="-1">豫之恒 <a class="header-anchor" href="#豫之恒" aria-label="Permalink to “豫之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>心多恨悔，出言為怪。梟鳴室北，聲醜可惡，請謁不得。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。坤為心、為悔恨，震為言、為出、為鳴，艮為梟、為室，坤北，故曰室北。震為聲，坤為醜、為惡，震為請謁，坤閉故不得。○恨悔，從元本，汲古作悔恨。《說苑》：&quot;齊景公為露寢之台，成而不通，柏常騫曰：台成，君何為不通？公曰：梟昔者鳴，其聲無不為，吾惡之甚。&quot;</p><h3 id="豫之遯" tabindex="-1">豫之遯 <a class="header-anchor" href="#豫之遯" aria-label="Permalink to “豫之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>離女去夫，閔思苦憂。齊子無良，使我心愁。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>下艮為夫，巽風故曰離女，風散故曰去夫。伏坤為苦憂，巽齊震子，坤惡故無良。坤為我、為心、為愁。○愁，依宋元本，汲古作悲。</p><h3 id="豫之大壯" tabindex="-1">豫之大壯 <a class="header-anchor" href="#豫之大壯" aria-label="Permalink to “豫之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>過時不歸，雌雄苦悲。徘徊外國，與叔分離。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《隨》。</p><h3 id="豫之晉" tabindex="-1">豫之晉 <a class="header-anchor" href="#豫之晉" aria-label="Permalink to “豫之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>鵲巢柳樹，鳩奪其處。任力薄德，天命不佑。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為鵲，離為巢，艮為木，故曰柳樹。離又為鳩，正居巢中，故曰鳩奪其處。</p><h3 id="豫之明夷" tabindex="-1">豫之明夷 <a class="header-anchor" href="#豫之明夷" aria-label="Permalink to “豫之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>鶴盜我珠，逃於東都。鵠怒追求，郭氏之墟。不見蹤跡，使我心憂。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為鶴、為珠，坎為盜，故曰盜珠。震為逃、為東，坤為都、為郭、為墟，震為鵠、為怒、為伯，坎為心憂。○鵠，依汲古，宋元本作懷，此有故實，今不能考。</p><h3 id="豫之家人" tabindex="-1">豫之家人 <a class="header-anchor" href="#豫之家人" aria-label="Permalink to “豫之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>夫婦相背，和氣弗處。陰陽俱否，莊薑無子。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《豫》象。震巽為夫婦，巽伏故曰相背。艮為背，正反艮故曰相背。坎為和，震起故弗處。卦一陽陷群陰中，而陰多無應，陰乘陽故曰俱否。巽為薑，震子，坤殺，故無子。震為莊。《詩》綠衣篇註：衛莊公惑於嬖，妾賢而無子。</p><h3 id="豫之睽" tabindex="-1">豫之睽 <a class="header-anchor" href="#豫之睽" aria-label="Permalink to “豫之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>日走月步，趣不同舍。妻夫反目，主君失位。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《豫》象。艮日坎月，上震，故曰步、曰走，正反震，故曰趣不同舍，艮為舍也。震為夫，坤為妻，《文言》雲臣道也，妻道也，是以坤為妻也。艮為目，正反艮故曰反目。震為玉、為君，艮為位，震在外，故曰失位，坎為失也。又《說文》：&quot;睽，兩目不相聽也&quot;，互坎為夫，離為坎妃，故曰夫妻。坎上下兩半目相背，故反目，是睽原有反目象也。○日走月步，從元本，宋本、汲古本皆作&quot;月走日步&quot;。趣，依汲古，宋元本作逃。位，依宋元本，汲古作居。</p><h3 id="豫之蹇" tabindex="-1">豫之蹇 <a class="header-anchor" href="#豫之蹇" aria-label="Permalink to “豫之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>雒陽嫁女，善逐人走。三寡失夫，婦妬無子。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此亦用《豫》象。坎水故曰洛，坤為都，故曰雒陽。坤為女，震為歸，故曰嫁女。震為人、為逐、為走，故曰善逐人走。坤為寡，震為夫，數三，坎失，故曰三寡失夫。坎為妬，震為子，坤為婦、為殺，故曰婦妬無子。</p><h3 id="豫之解" tabindex="-1">豫之解 <a class="header-anchor" href="#豫之解" aria-label="Permalink to “豫之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>周德既成，杼軸不傾。太宰東西，夏國康寧。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為周，坎為杼軸，震為宰、為東，坎為西，離為夏。夏國，大國也。坎又為平，故不傾。</p><h3 id="豫之損" tabindex="-1">豫之損 <a class="header-anchor" href="#豫之損" aria-label="Permalink to “豫之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>日中為市，交易資寶。各利所有，心悅以喜。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>通《咸》。乾為日，在中爻，故曰日中。中巽為市、為交易，巽為寶，巽為利，兌悅震喜，坤為心。○各，依宋元本，汲古作名。○坤為心證。</p><h3 id="豫之益" tabindex="-1">豫之益 <a class="header-anchor" href="#豫之益" aria-label="Permalink to “豫之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>童妾獨宿，長女未室，利無所得。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>伏兌為妾、為少女，故曰童妾，坤寡故獨宿。巽為長女，艮為室，巽寡故未室。巽為利，坤喪故無得。○童，依宋元本，汲古作僮。</p><h3 id="豫之夬" tabindex="-1">豫之夬 <a class="header-anchor" href="#豫之夬" aria-label="Permalink to “豫之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>忠言輔成，王政不傾。公劉兆基，文武綏之。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為王、為成、為言。</p><h3 id="豫之姤" tabindex="-1">豫之姤 <a class="header-anchor" href="#豫之姤" aria-label="Permalink to “豫之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>牛驥同槽，郭氏以亡。國破為虛，主君奔逃。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《晉》。郭亡見《說苑》，詳前。</p><h3 id="豫之萃" tabindex="-1">豫之萃 <a class="header-anchor" href="#豫之萃" aria-label="Permalink to “豫之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>中原有菽，以待饔食。飲御諸友，所求大得。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《大過》。惟各本饔皆作雉，茲依《大過》林改。</p><h3 id="豫之升" tabindex="-1">豫之升 <a class="header-anchor" href="#豫之升" aria-label="Permalink to “豫之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>多虛少實，語不可知。尊空無酒，飛言如雨。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>陰多陽少，故曰多虛少實。震為言語，坤亂故不可知。震為樽，兌為酒，坤虛故空無。震言，兌亦為言，言多故如雨。兌為雨。○知，依汲古，宋元本作覆。</p><h3 id="豫之困" tabindex="-1">豫之困 <a class="header-anchor" href="#豫之困" aria-label="Permalink to “豫之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>青蠅集蕃，君子信讒。害賢傷忠，患生婦人。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>蕃，《毛詩》作樊，義皆通藩。《周官大司徒》蕃樂，杜子春讀蕃為藩，是其證，刺幽王詩也。巽為蠅，東方本色青，故曰青蠅。伏艮為蕃、為君子，三至上正覆兌相背，故曰讒。《困》彖曰&quot;有言不信&quot;，林所本也。坎為忠、為害、為患，巽為婦，伏震為人。○汲古作&quot;君信讒言&quot;，依宋本。</p><h3 id="豫之井" tabindex="-1">豫之井 <a class="header-anchor" href="#豫之井" aria-label="Permalink to “豫之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>履株覆輿，馬驚傷車，步為我憂。通《噬嗑》。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>震為株、為輿、為履，二至四震覆，故曰覆輿。震為馬、為驚，坎破，故車傷。震為步，坎為憂，言行路難也。</p><h3 id="豫之革" tabindex="-1">豫之革 <a class="header-anchor" href="#豫之革" aria-label="Permalink to “豫之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>商風召寇，來呼外盜。間諜內應，與我爭鬬。殫已寶藏，主人不勝。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>兌西正秋，互巽，故曰商風。巽為伏、為寇盜。《史記天官書》：&quot;風從南方來，大旱；西方，有兵。&quot;，故曰召寇，二至上正覆兌，故曰間諜、曰爭鬬。乾為寶，震為主人，震伏故不勝。○第二句汲古作&quot;呼我北盜&quot;，依宋元本。</p><h3 id="豫之鼎" tabindex="-1">豫之鼎 <a class="header-anchor" href="#豫之鼎" aria-label="Permalink to “豫之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>逸豫好游，不安其家。惑於少姬，久迷不來。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>伏震為樂，故曰逸豫。震為游，伏艮為家，坎險故不安。兌為少姬，伏坤為迷。此有故實，不能確指。○惑於少姬，依宋元本，汲古作惑有，非。</p><h3 id="豫之震" tabindex="-1">豫之震 <a class="header-anchor" href="#豫之震" aria-label="Permalink to “豫之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>吾有驊騮，畜之以時。東家翁孺，來請我駒。價極可與，後無賤悔。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為馬，艮為止、為畜、為時、為家，震東，故曰東家。艮為祖、為少男，故曰翁孺。震為請、為駒、為後，坎為悔。○賤，從宋元，汲古作賊，林意言馬已得善價，可與之不致後悔也。</p><h3 id="豫之艮" tabindex="-1">豫之艮 <a class="header-anchor" href="#豫之艮" aria-label="Permalink to “豫之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>厄窮上通，與堯相逢。登升大麓，國無凶人。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>陽窮在上，故曰厄窮上通。互震為帝，故曰堯，三上正反震故曰相逢。震為登、為升，艮為山麓、為國，震為人，震樂，故無凶人。《虞書》：&quot;納於大麓，烈風雷雨弗迷&quot;，謂舜。</p><h3 id="豫之漸" tabindex="-1">豫之漸 <a class="header-anchor" href="#豫之漸" aria-label="Permalink to “豫之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>眾兔俱走，熊羆在後。踦不能進，失信寡處。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>伏震為兔、為走，坎眾，故曰眾兔俱走。艮為熊羆，震為後，坎蹇故踦，艮止故不進。坎為信、為失，巽為寡。○踦，依宋元本，汲古作騎，非。</p><h3 id="豫之歸妹" tabindex="-1">豫之歸妹 <a class="header-anchor" href="#豫之歸妹" aria-label="Permalink to “豫之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>旁行不遠，三思復返。心多畏惡，日中止舍。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為行、為返，坎為思，震數三，故曰三思。坎為心、為畏、為中，離為日，伏艮為止、為舍。○惡，依宋元本，汲古作患。</p><h3 id="豫之豐" tabindex="-1">豫之豐 <a class="header-anchor" href="#豫之豐" aria-label="Permalink to “豫之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>倉唐奉使，中山以孝。文侯悅喜，擊子徵召。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>元本註：魏太子擊封中山，三年不召，其傅趙倉唐請使，魏文侯大悅，召擊子立之。伏艮為倉、為山，巽順故曰孝。離為文，震為侯、為喜、為子，艮手故曰擊子。震為召。○倉唐，從宋元本，汲古作倉皇，非。</p><h3 id="豫之旅" tabindex="-1">豫之旅 <a class="header-anchor" href="#豫之旅" aria-label="Permalink to “豫之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>入天門，守地戶。君安樂，不勞苦。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為門，陽在上為天，巽入，故曰入天門。先天艮居戌亥，《乾鑿度》以乾為天門，與艮同位，故艮亦為天門，巽為地戶，而艮為守、為戶牑，故曰守地戶。伏震為君、為樂。○地戶，依宋元本，汲古作城戶，非。○汲古下有&quot;文山蹲鴟，肥腯多脂。王孫獲願，載福巍巍&quot;四句，宋元本同，惟勞苦下多&quot;一說&quot;二字，顯為另一林詞，與上三字句文不相屬。○艮為天證。</p><h3 id="豫之巽" tabindex="-1">豫之巽 <a class="header-anchor" href="#豫之巽" aria-label="Permalink to “豫之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>登階上堂，見吾父兄。左酒右漿，與福相迎。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。為登。艮為堂、為階，震為父、為兄、為左，兌為右，互大坎為酒漿，震又為福。</p><h3 id="豫之兌" tabindex="-1">豫之兌 <a class="header-anchor" href="#豫之兌" aria-label="Permalink to “豫之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>秋蛇向穴，不失其節。夫人薑氏，自齊復入。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌正秋，巽為蛇，兌為穴，互巽為齊、為薑，伏震為人、為夫。《左傳》：&quot;莊薑與齊襄通，屢赴齊會齊侯。&quot;</p><h3 id="豫之渙" tabindex="-1">豫之渙 <a class="header-anchor" href="#豫之渙" aria-label="Permalink to “豫之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>忍醜少羞，無面有頭。耗減寡虛，日以削消。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>象多未詳。○耗滅、削消，依汲古，宋元本作滅耗、作削瑣，非。</p><h3 id="豫之節" tabindex="-1">豫之節 <a class="header-anchor" href="#豫之節" aria-label="Permalink to “豫之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>景星照堂，麟游鳳翔。仁施大行，頌聲大興。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為星，伏離為日，亦為星，故曰景星。艮為堂，伏離為文，故曰麟鳳。互震為游翔、為仁、為聲、為行。○麟游鳳翔，依汲古，宋元作&quot;麟鳳游翔&quot;。</p><h3 id="豫之中孚" tabindex="-1">豫之中孚 <a class="header-anchor" href="#豫之中孚" aria-label="Permalink to “豫之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>乾旄旌旗，執幟在郊。雖有寶珠，無路致之。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《隨》。</p><h3 id="豫之小過" tabindex="-1">豫之小過 <a class="header-anchor" href="#豫之小過" aria-label="Permalink to “豫之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>李華再實，鴻卵降集。仁德以興，蔭國受福。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《離》。</p><h3 id="豫之既濟" tabindex="-1">豫之既濟 <a class="header-anchor" href="#豫之既濟" aria-label="Permalink to “豫之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>白馬赤烏，戰於東都。天輔有德，敗悔為憂。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《豫》象。震為白、為馬，艮為烏，坎赤，故曰白馬赤烏。震為東，坤為都，正反艮，故曰戰於東都。艮為天，坎為憂。《史記》：&quot;武王渡河，有火流於王屋，化為赤烏&quot;，丁晏雲《詩》&quot;有客有客，亦白其馬&quot;，蓋白馬為殷人昕尚。東都指牧野。○第三句汲古無，依宋元本補。</p><h3 id="豫之未濟" tabindex="-1">豫之未濟 <a class="header-anchor" href="#豫之未濟" aria-label="Permalink to “豫之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>採薪得麟，大命隕顛。豪雄爭名，天下四分。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《坤》。此取遇卦《豫》象。坤為薪、為麟，艮手為採，坎為獲，故曰採薪得麟。伏巽為命、為隕顛，乾為大，故大命隕顛。震為豪雄，艮為名，正反艮故爭名。坤為天下，坎為分，震卦數四，故曰天下四分。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
